Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

// Markdown to HTML converter function
std::string md_to_html(const std::string& markdown) {
    // Define regex patterns for Markdown formatting
    std::regex bold_regex("\\*([^*]*)\\*");
    std::regex italic_regex("\\_([^_]*)\\_");
    std::regex link_regex("\\[([^\\]]*)\\]\\(([^\\)]*)\\)");
    std::regex header_regex("^(#{1,6})\\s+(.+)$");
    std::regex code_block_regex("^(`{3})(.+)\\1$");
    std::regex block_quote_regex("^> (.+)$");

    std::stringstream html_stream;

    // Replace Markdown formatting with corresponding HTML tags
    std::string markdown_copy = markdown;
    std::smatch match;

    while (std::regex_search(markdown_copy, match, bold_regex)) {
        std::string bold_text = match[1].str();
        markdown_copy.replace(match.position(), match.length(), "<strong>" + bold_text + "</strong>");
    }

    while (std::regex_search(markdown_copy, match, italic_regex)) {
        std::string italic_text = match[1].str();
        markdown_copy.replace(match.position(), match.length(), "<em>" + italic_text + "</em>");
    }

    while (std::regex_search(markdown_copy, match, link_regex)) {
        std::string link_text = match[1].str();
        std::string link_url = match[2].str();
        markdown_copy.replace(match.position(), match.length(), "<a href=\"" + link_url + "\">" + link_text + "</a>");
    }

    while (std::regex_search(markdown_copy, match, header_regex)) {
        std::string header_symbol = std::string(match[1].str(), '#');
        std::string header_text = match[2].str();
        int header_level = header_symbol.length();
        markdown_copy.replace(match.position(), match.length(), "<h" + std::to_string(header_level) + ">" + header_text + "</h" + std::to_string(header_level) + ">");
    }

    while (std::regex_search(markdown_copy, match, code_block_regex)) {
        std::string delimiter = match[1].str();
        std::string code_block_text = match[2].str();
        markdown_copy.replace(match.position(), match.length(), "<pre><code>" + code_block_text + "</code></pre>");
    }

    while (std::regex_search(markdown_copy, match, block_quote_regex)) {
        std::string block_quote_text = match[1].str();
        markdown_copy.replace(match.position(), match.length(), "<blockquote>" + block_quote_text + "</blockquote>");
    }

    html_stream << markdown_copy;

    return html_stream.str();
}

int main() {
    std::string markdown_text = "Hello **world**! _This is italic_. [Google](https://www.google.com/) is a search engine. # Header 1\n## Header 2\n### Header 3\n#### Header 4\n##### Header 5\n###### Header 6\n```
    This is a code block.
    ```\n> This is a blockquote.";

    std::string html_text = md_to_html(markdown_text);

    std::cout << "Markdown:\n" << markdown_text << "\n\nHTML:\n" << html_text << std::endl;

    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les différentes formattages de Markdown et les remplacer par les correspondantes balises HTML. Les différentes formattages de Markdown sont traités séparément, en utilisant des regex pour trouver les chaînes de caractères correspondantes dans le texte de l'entrée. La fonction utilise ensuite un flux de chaînes pour générer le texte HTML final. 

Notez que cette implémentation n'est pas exhaustive, car il existe d'autres formattages de Markdown tels que les listes, les tableaux, les images, etc. Cependant, cette fonction peut être une bonne base pour ajouter davantage de fonctionnalités selon les besoins.

