function isPrime(number) {
  if (number <= 1) {
    return false;
  }

  for (let I = 2; I <= Math.sqrt(number); i++) {
    if (number % I === 0) {
      return false;
    }
  }

  return true;
}

function checkForPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
